# Generated by build.py from recipe.yml for recipe mqtt-test-a-sensor-to-alert-flow. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'alert.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The service: mails ops@example.com when a sensor's temperature is past the limit.`n# Usage: sh alert.sh <mqtt port> <smtp port> <sensor> <limit>`ntopic=sensors/`$3/temp`nreading=`"`"`nfor try in 1 2 3 4 5; do`n  # A subscriber is sent the topic's length in two bytes, the topic, then the payload.`n  reading=`$(curl -s -m 5 `"mqtt://127.0.0.1:`$1/`$topic`" | tail -c +`$(( `${#topic} + 3 )))`n  [ -n `"`$reading`" ] && break`n  sleep 1`ndone`nif [ -z `"`$reading`" ]; then`n  echo `"no reading from `$3`"`n  exit 1`nfi`nif awk -v r=`"`$reading`" -v l=`"`$4`" 'BEGIN { exit !(r + 0 > l + 0) }'; then`n  printf 'From: sensors@example.com\r\nTo: ops@example.com\r\nSubject: %s at %s C\r\n\r\n%s reads %s C, past the limit of %s C.\r\n' \`n    `"`$3`" `"`$reading`" `"`$3`" `"`$reading`" `"`$4`" > alert.eml`n  curl -sS --mail-from sensors@example.com --mail-rcpt ops@example.com -T alert.eml `"smtp://127.0.0.1:`$2/`" || exit 1`n  echo `"alert sent for `$3 at `$reading`"`nelse`n  echo `"no alert for `$3 at `$reading`"`nfi`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"sensors/#;retain"', 'mqtt://127.0.0.1:8080/', 'smtp://127.0.0.1:8081/', 'pop3://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -d 81.5 mqtt://127.0.0.1:8080/sensors/boiler/temp && sh alert.sh 8080 8081 boiler 75 } finally { Stop-Process $server0 }
